 function highlight(){[...list.children].forEach((el,i)=>el.setAttribute('aria-selected',String(i===cursor)));if(cursor>=0){input.setAttribute('aria-activedescendant',list.children[cursor].id);list.children[cursor].scrollIntoView({block:'nearest'});}}
 function draw(){const q=value.value?'':input.value.trim().toLocaleLowerCase();matches=people.filter(e=>[e.name_ar,e.name_en,e.employee_no,e.iqama].join(' ').toLocaleLowerCase().includes(q)).sort(hierarchyCompare);list.replaceChildren();cursor=-1;input.removeAttribute('aria-activedescendant');for(const [i,e] of matches.entries()){const row=document.createElement('div');row.id=list.id+'-'+i;row.setAttribute('role','option');row.setAttribute('aria-selected','false');row.textContent=employeeName(e)+' · '+e.employee_no;row.onmousedown=ev=>ev.preventDefault();row.onclick=()=>choose(e);list.append(row);}if(!matches.length){const empty=document.createElement('p');empty.textContent=tr('لا يوجد موظف مطابق','No matching employee');list.append(empty);}list.hidden=false;input.setAttribute('aria-expanded','true');}
 input.onfocus=draw;input.oninput=()=>{value.value='';onchange();draw();};input.onblur=close;
