if(type==='profile'&&sections.includes('details')){const e=selected[0];content+=table([tr('البيان','Field'),tr('القيمة','Value')],[[tr('الاسم بالعربية','Arabic name'),e.name_ar],[tr('الاسم بالإنجليزية','English name'),e.name_en],[tr('الرقم الوظيفي','Employee number'),e.employee_no],[tr('الهوية','Identity'),e.iqama],[tr('الجوال','Mobile'),e.phone],[tr('البريد','Email'),e.email],[tr('الجنسية','Nationality'),e.nationality],[tr('البوزيشن','Position'),e.position],[tr('الجريد','Grade'),e.grade],[tr('القسم','Department'),e.department],[tr('الحالة','Status'),statusLabel(e.employment_status)]]);}
 if(type==='profile'&&sections.includes('history')){let cursor=null;const seen=new Set(),rows=[];do{const r=await api('advacon_people_history',{p_employee_id:selected[0].id,p_before_id:cursor});for(const h of r.items){const before=h.before_value||{},after=h.after_value||{},keys=['asset_label','asset_action','target_employee_name','effective_at','housing_location','housing_date','name_ar','name_en','employee_no','phone','email','nationality','position','grade','department','employment_status','project_ref','role_label','starts_on','ends_on'];const changes=keys.filter(k=>JSON.stringify(before[k]??null)!==JSON.stringify(after[k]??null)).map(k=>(before[k]??'—')+' → '+(after[k]??'—')).join(' / ');rows.push([dateText(h.created_at),h.actor_label,changes||tr('تحديث ارتباط بالسجل','Record link updated')]);}cursor=r.next_before_id;if(cursor&&seen.has(cursor))throw Error('history_cursor_repeated');seen.add(cursor);}while(cursor);content+='<h2>'+tr('سجل التغييرات','Change history')+'</h2>'+table([tr('التاريخ','Date'),tr('بواسطة','By'),tr('التغيير','Change')],rows);}
