 if(type==='profile'&&sections.includes('projects'))content+='<h2>'+tr('المشاريع والمدير','Projects & manager')+'</h2>'+table([tr('المشروع','Project'),tr('المدير','Manager'),tr('الدور','Role'),tr('من','From'),tr('إلى','To')],assignments.filter(a=>selectedIds.has(a.employee_id)).map(a=>[projectLabel(projectRegistry.find(p=>p.id===a.project_id||p.code===a.project_ref)),employeeName(people.find(p=>p.id===a.manager_id)||{name_ar:tr('غير محدد','Not specified')}),a.role_label,a.starts_on,a.ends_on||tr('مستمر','Ongoing')]));
 if(type==='profile'&&sections.includes('housing')){const r=await api('advacon_employee_housing',{p_employee_id:selected[0].id});content+='<h2>'+tr('السكن','Housing')+'</h2>'+table([tr('العقار','Property'),tr('الغرفة','Room'),tr('من','From'),tr('إلى','To')],r.assignments.map(a=>[(ar()?a.property_name:a.property_name_en||a.property_name)||a.property_code,a.space||a.space_code,a.starts_on,a.ends_on||tr('حالي','Current')]));}
 if(type==='transfers'){const events=[],lower=from?Date.parse(from+'T00:00:00+03:00'):-Infinity,upper=to?Date.parse(to+'T23:59:59.999+03:00'):Infinity,person=id=>id?employeeName(people.find(e=>e.id===id)||{name_ar:'—'}):tr('المخزون المتاح','Available stock');for(const mode of ['vehicle','card']){const key=mode==='vehicle'?'vehicle_id':'card_id',rows=assetRows(data,mode);for(const a of rows){const prev=rows.find(p=>p[key]===a[key]&&p.ends_on&&Date.parse(p.ends_on)===Date.parse(a.starts_on));const time=Date.parse(a.starts_on),item=assetList(data,mode).find(x=>x.id===a[key]);if(time>=lower&&time<=upper&&(selectedIds.has(a.employee_id)||selectedIds.has(prev?.employee_id)))events.push([time,mode,item?assetLabel(mode,item):'—',person(prev?.employee_id),person(a.employee_id)]);if(a.ends_on&&!rows.some(n=>n[key]===a[key]&&Date.parse(n.starts_on)===Date.parse(a.ends_on))){const end=Date.parse(a.ends_on);if(end>=lower&&end<=upper&&selectedIds.has(a.employee_id))events.push([end,mode,item?assetLabel(mode,item):'—',person(a.employee_id),person(null)]);}}}content+=table([tr('التاريخ','Date'),tr('النوع','Type'),tr('العهدة','Asset'),tr('من','From'),tr('إلى','To')],events.sort((a,b)=>b[0]-a[0]).map(([t,mode,...rest])=>[dateText(new Date(t).toISOString()),tr(mode==='vehicle'?'سيارة':'بطاقة',mode==='vehicle'?'Vehicle':'Card'),...rest]));}

 return '<!doctype html><html lang="'+(ar()?'ar':'en')+'" dir="'+(ar()?'rtl':'ltr')+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ADVACON — '+esc(titles[type])+'</title><style>@page{size:A4 landscape;margin:16mm 12mm 18mm;@top-right{content:"ADVACON";font:8pt Arial;color:#61758b}@bottom-center{direction:ltr;unicode-bidi:isolate;content:counter(page) " / " counter(pages);font:9pt Arial;color:#61758b}}*{box-sizing:border-box}body{font:11px Arial,sans-serif;color:#173652;margin:0;line-height:1.6}header{border-bottom:3px solid #173f6b;margin-bottom:20px;padding-bottom:12px;display:flex;justify-content:space-between;gap:20px}h1{font-size:23px;margin:0}h2{font-size:16px;margin:24px 0 10px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:12px 0}th{background:#173f6b;color:#fff;text-align:start}th,td{padding:7px 6px;border:1px solid #d8e2eb;overflow-wrap:anywhere;vertical-align:top}tr{break-inside:avoid}thead{display:table-header-group}tbody tr:nth-child(even){background:#f4f7fa}.meta,.note{color:#5d7286}.meta{margin:8px 0}.note{font-size:10px}header strong{font-size:22px;letter-spacing:2px}@media screen{body{padding:22px;background:#fff;min-width:0}.report-table-scroll{max-width:100%;overflow-x:auto}table{min-width:760px}header{flex-wrap:wrap}@media(max-width:600px){body{padding:12px}h1{font-size:20px}}}@media print{.report-table-scroll{overflow:visible}}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><header><div><img alt="ADVACON" src="data:image/png;base64," style="width:145px;height:47px;object-fit:contain;display:block"></div><div><h1>'+esc(titles[type])+'</h1><div>'+esc(dateText(new Date().toISOString()))+'</div></div></header><p class="meta">'+tr('الاختيارات (الموظف / المشروع الحالي / الجريد / الحالة): ','Filters (employee / current project / grade / status): ')+esc(filters.join(' / '))+(type==='transfers'?' · '+esc(from||'—')+' — '+esc(to||'—'):'')+'</p><p class="meta">'+selected.length+' '+tr('موظف ضمن الاختيار','employees selected')+'</p>'+content.replace(/<table>/g,'<div class="report-table-scroll" tabindex="0" role="region" aria-label="'+tr('جدول التقرير، مرّر لعرض الأعمدة','Report table, scroll to view columns')+'"><table>').replace(/<\/table>/g,'</table></div>')+'</body></html>';
