async function beginAssetService(e,service){
 profile(e,'assets',true);const panel=host.querySelector('.org-profile-content');panel.textContent=tr('جارٍ التحميل…','Loading…');try{const data=await api('advacon_fleet_list');if(!panel.isConnected||activeProfile?.id!==e.id||activeProfile.tab!=='assets')return;if(!Array.isArray(data.card_custody))throw new Error(tr('تعذر فتح العهد حاليًا. أعد تحميل الصفحة، وتواصل مع المسؤول إذا استمرت المشكلة.','Assets are unavailable. Reload the page and contact your administrator if the problem persists.'));if(service==='asset_add'){addProfileAsset(e,data);return;}
 const mode=service.startsWith('vehicle_')?'vehicle':'card',owned=assetList(data,mode).filter(x=>assetHolder(data,mode,x.id)?.employee_id===e.id);panel.innerHTML='<div class="org-service-picker"><h2>'+esc(assetServices().find(([k])=>k===service)?.[1]||'')+'</h2></div>';const body=panel.firstElementChild;
 if(!owned.length){body.insertAdjacentHTML('beforeend','<p>'+tr('لا توجد عهدة مناسبة مسندة لهذا الموظف.','No assigned asset for this action.')+'</p>');body.append(button(tr('العودة لاختيار الإجراء','Back to actions'),()=>profile(e,'assets')));return;}
 const fields=document.createElement('div');fields.className='org-form';body.append(fields);const select=labeledSelect(fields,tr('العهدة الحالية','Current asset'),'asset',owned.map(x=>({value:x.id,label:assetLabel(mode,x)})));if(owned.length===1)select.value=owned[0].id;
 body.append(button(tr('متابعة','Continue'),()=>{const item=owned.find(x=>x.id===select.value);if(!item){select.required=true;select.reportValidity();select.focus();return;}if(service==='balance')form(tr('تحديث رصيد البطاقة','Update card balance'),[{key:'amount',label:tr('الرصيد SAR','Balance SAR'),type:'number',required:true,min:0,step:'.01'},{key:'observed_at',label:tr('تاريخ القياس إن عُرف','Observation time, if known'),type:'datetime-local'},{key:'notes',label:tr('ملاحظة','Note')}],{},'fuel.balance',{id:item.id,source:'Employee actions'});else assetOperation(e,data,mode,item,service.split('_')[1]);},'btn'));
 }catch(err){if(panel.isConnected&&activeProfile?.id===e.id&&activeProfile.tab==='assets'){AdvaconUI.errorState(panel,err,()=>beginAssetService(e,service));panel.append(button(tr('العودة لاختيار الإجراء','Back to actions'),()=>profile(e,'assets')));}}
}

async function renderEmployeeRequests(e,panel){
 panel.innerHTML='<h2>'+tr('طلبات الموظف','Employee requests')+'</h2><p>'+tr('نفس الطلبات المسجلة بأرشيف الإدارة وأرقامها الأصلية.','The same requests and original task numbers as the administration register.')+'</p>';
 const list=document.createElement('div');list.className='org-record-list';panel.append(list);let before=null;
 const more=button(tr('تحميل الطلبات','Load requests'),async()=>{more.disabled=true;try{const r=await api('advacon_employee_requests',{p_employee_id:e.id,p_before_id:before});if(!panel.isConnected)return;for(const item of r.items){const row=document.createElement('article');row.className='org-record';row.innerHTML='<strong>TSK-'+esc(String(item.id).padStart(4,'0'))+'</strong><p>'+esc(item.title)+'</p><small>'+esc(item.project)+' · '+esc(item.status)+' · '+esc(item.received_at||item.received||'—')+'</small>';list.append(row);}if(!r.total)list.textContent=tr('لا توجد طلبات مرتبطة بعد.','No linked requests yet.');before=r.items.at(-1)?.id;more.hidden=r.items.length<50;more.textContent=tr('عرض المزيد','Show more');}catch(err){if(panel.isConnected){list.textContent=tr('تعذر عرض الطلبات. تحقق من صلاحية الإدارة وتثبيت التحديث.','Requests unavailable. Check administrator access and install the update.');}}finally{more.disabled=false;}},'btn sec');panel.append(more);more.click();
}

